import React from 'react';
import { observer } from 'mobx-react-lite';
import { createStyles } from '@nocobase/client';
import {
  ExportOutlined,
  FieldTimeOutlined,
  HeartOutlined,
  MessageOutlined,
  PlayCircleOutlined,
} from '@ant-design/icons';
import { Image } from 'antd';
import { useEvent } from '../hooks';
import { isFunction } from 'lodash';

export interface ITKVideoCardProps {
  coverSize?: {
    width: string;
    height: string;
  };
  video: {
    id?: string;
    duration?: string;
    viewCount?: string;
    diggCount?: string;
    commentCount?: string;
    shareCount?: string;
    coverUrl: string;
    videoUrl?: string;
    customClick?: (e: MouseEvent) => {};
  };
}

const useStyles = createStyles(({ css }) => {
  return {
    card: css`
      display: flex;
      flex-flow: row;
      align-items: center;
    `,
    videoContainer: css`
      border-radius: 6px;
      overflow: hidden;
    `,
    videoCover: css`
      width: 100%;
      height: 100%;
      border-radius: 6px;
    `,
    infoContainer: css`
      display: flex;
      flex-flow: column;
      width: 38px;
      padding: 14px 10px;
      gap: 3px 0;
    `,
    indicator: css`
      display: flex;
      flex-flow: column;
      align-items: center;
    `,
    indicatorIcon: css`
      font-size: 14px;
    `,
    indicatorContent: css`
      margin-top: 2px;
      font-size: 11px;
    `,
  };
});

const TKVideoCard: React.FC<ITKVideoCardProps> = observer((props) => {
  const { video, coverSize = { width: 200, height: 300 } } = props;
  const { coverUrl, duration, videoUrl, viewCount, diggCount, shareCount, commentCount, customClick } = video;
  const { styles } = useStyles();
  const noPreview = !isFunction(customClick);

  const handleClick = useEvent((e: any) => {
    e.stopPropagation();
  });

  return (
    <div className={styles.card}>
      <div className={styles.videoContainer} onClick={handleClick}>
        <Image
          preview={noPreview}
          width={coverSize.width}
          height={coverSize.height}
          src={coverUrl}
          fallback="data:image/png;base64,"
        />
      </div>
      <div className={styles.infoContainer}>
        <div className={styles.indicator}>
          <FieldTimeOutlined className={styles.indicatorIcon} />
          <div className={styles.indicatorContent}>{duration}</div>
        </div>
        <div className={styles.indicator}>
          <PlayCircleOutlined className={styles.indicatorIcon} />
          <div className={styles.indicatorContent}>{viewCount}</div>
        </div>
        <div className={styles.indicator}>
          <HeartOutlined className={styles.indicatorIcon} />
          <div className={styles.indicatorContent}>{diggCount}</div>
        </div>
        <div className={styles.indicator}>
          <MessageOutlined className={styles.indicatorIcon} />
          <div className={styles.indicatorContent}>{commentCount}</div>
        </div>
        <div className={styles.indicator}>
          <ExportOutlined className={styles.indicatorIcon} />
          <div className={styles.indicatorContent}>{shareCount}</div>
        </div>
      </div>
    </div>
  );
});

TKVideoCard.displayName = 'TKVideoCard';

export default TKVideoCard;
